parts.script:
if (ctx.state.done) {
  ctx.log(`Already created ${ctx.state.count} part(s) earlier — guarded by ctx.state.done so this only runs once. (Without a guard, creating something every tick would hit the parts+connectors cap fast under continuous Run.)`);
  return { value: ctx.state.count, state: ctx.state };
}

// Same model as this node: create two capabilities and wire them to this node.
const capA = ctx.createPart({ type: 'BusinessCapability', label: 'Generated Capability A', model: ctx.part.model });
ctx.createConnector({ from: ctx.part.id, to: capA.id, connectorType: 'c', relationship: 'Association' });

const capB = ctx.createPart({ type: 'BusinessCapability', label: 'Generated Capability B', model: ctx.part.model });
ctx.createConnector({ from: ctx.part.id, to: capB.id, connectorType: 'c', relationship: 'Association' });

// A DIFFERENT model: no connector here — a connector needs both ends in the same
// model to make sense on any view, so cross-model creation is create-only.
const capC = ctx.createPart({ type: 'BusinessCapability', label: 'Generated Capability C (other model)', model: 'Generated' });

ctx.log(`Created "${capA.label}" and "${capB.label}" in this node's own model ("${ctx.part.model}"), each wired to this node with a new connector.`);
ctx.log(`Created "${capC.label}" in a DIFFERENT model ("${capC.model}") — cross-model creation.`);
ctx.log('None of these have a viewMember yet — check Catalogs > Parts, or the Script Console.');

return {
  value: 3,
  state: { done: true, count: 3, capAId: capA.id, capBId: capB.id, capCId: capC.id },
};
